/* ──────────────────────────────────────────────────────────────────────────
   GoVocal city theme switcher
   The product themes three colours per tenant (city): primary, secondary, text
   (front/app/component-library/utils/styleUtils.ts → getTheme()).
   This drives those three CSS variables from a `?theme=` URL param and renders a
   small live picker so a prototype can be previewed across several city palettes.

   Usage in a prototype:
     <link rel="stylesheet" href="govocal-tokens.css">
     <link rel="stylesheet" href="govocal-ui.css">
     <script src="govocal-themes.js" defer></script>
   Then build with var(--gv-tenant-primary) / -secondary / -text (never hardcode
   brand colours). Open ?theme=2 to preview a city, or use the on-screen picker.

   Add a template: append to GV_THEMES. Each city sets only the 3 tenant colours;
   tints + focus + component states derive from them automatically.

   City logos (for realism): give a theme a `logo` (an HTML string — inline <svg>
   or <img src="logos/ocean.svg">) and any element with `data-gv-logo` renders it,
   swapping live with the theme. Until a real logo is set, a clean placeholder
   (city mark + name) is generated automatically. Example slot in a header:
     <a class="brand" data-gv-logo aria-label="City home"></a>
   ────────────────────────────────────────────────────────────────────────── */
(function () {
  // ── City logos (inline SVG recreations of each tenant's mark + wordmark). ──
  // Replace any of these with the official asset (inline <svg> or <img src>) anytime.
  // Real captured tenant marks (high-res uploads from each live platform, optimized + inlined
  // as data URIs so the theme file stays self-contained). Rendered at header height; width auto.
  function imgLogo(uri, alt) {
    // No inline height — slot CSS (injected below) sizes it: header 44px (matches the
    // live product), mobile 34px, footer 28px. Square marks then fill the height and read big.
    return '<img class="gv-logo" src="' + uri + '" alt="' + (alt || '') + '" ' +
      'style="width:auto;object-fit:contain;display:block">';
  }

  var LOGO_WIEN = imgLogo('data:image/png;base64,', "Stadt Wien");
  var LOGO_LINZ = imgLogo('data:image/png;base64,', "Wirtschaft & Innovation Linz");
  var LOGO_STLOUIS = imgLogo('data:image/jpeg;base64,', "City of St. Louis");
  var LOGO_OSLO = imgLogo('data:image/png;base64,', "Oslo kommune");
  var LOGO_LAMBETH = imgLogo('data:image/png;base64,', "London Borough of Lambeth");
  var LOGO_DUBLIN = imgLogo('data:image/png;base64,', "Dublin City");
  var LOGO_LOKEREN = imgLogo('data:image/jpeg;base64,', "Stad Lokeren");

  var LOGO_KBH = imgLogo('data:image/png;base64,', 'Københavns Kommune');

  var LOGO_CA =
    '<span style="display:inline-flex;align-items:center;gap:9px;font-family:var(--gv-font-family,sans-serif)">' +
    '<svg width="38" height="31" viewBox="0 0 46 38" aria-hidden="true">' +
    '<path d="M25 4h12a6 6 0 0 1 6 6v8a6 6 0 0 1-6 6h-1v5l-6-5h-5a6 6 0 0 1-6-6v-8a6 6 0 0 1 6-6Z" fill="#E79450"/>' +
    '<path d="M9 1h12a6 6 0 0 1 6 6v8a6 6 0 0 1-6 6h-5l-6 5v-5H9a6 6 0 0 1-6-6V7a6 6 0 0 1 6-6Z" fill="#1C2745"/></svg>' +
    '<span style="line-height:1;color:#1C2745"><span style="font-weight:800;font-size:15px;letter-spacing:-.01em">Engaged</span>' +
    '<br><span style="font-weight:700;font-size:9px;letter-spacing:.14em">CALIFORNIA</span></span></span>';


  // REAL city tenants only (the GoVocal house theme was removed). Brand values are
  // LIVE-CAPTURED from each platform (getComputedStyle on the homepage; primary = the
  // colour the product fills its primary buttons with — authoritative, never eyeballed).
  // id 0 = Linz is the default (applied when no ?theme=); then Dublin, then Wien.
  //   Linz              #604596 (purple); custom font LentiaNova-Neutral.
  //   Dublin City       #0077A3 (teal); Public Sans.
  //   Stadt Wien        #FF5A64 (rgb 255,90,100) — the real in-product red, text #000000.
  //                     (Supersedes earlier #FF0000/#FF1D2B guesses — both were wrong.)
  //   Københavns Kommune #000C2E (live-captured = Pantone 296C); custom font KBH-Regular; real city-seal logo.
  //   City of St. Louis #033D8B (deep blue); Public Sans.    Oslo kommune #034B45 (green); custom font OsloSans-Regular.
  //   Lambeth #246797 · Stad Lokeren #025157 — both Public Sans.   Engaged California #1C2745 (best-effort, not captured).
  // secondary = primary darkened ~18% (the product derives hover/active from primary; the
  //   homepage exposes no distinct configured secondary, so we derive a coherent one).
  // Custom city faces (Lentia Nova, Oslo Sans, Wiener Melange, KBH) are proprietary; the real
  // woff2 masters are bundled below (@font-face, data URI) so they actually render — each stack
  // names the real face first, then a free Google-Fonts substitute, then Public Sans.
  var FONT_FALLBACK = '"Public Sans", "Helvetica Neue", Helvetica, Arial, sans-serif';
  var GV_THEMES = [
    { id: 0, name: 'Linz',                primary: '#604596', secondary: '#4F397B', text: '#313131', logo: LOGO_LINZ,    font: '"LentiaNova-Neutral", "Figtree", ' + FONT_FALLBACK },
    { id: 1, name: 'Dublin City',         primary: '#0077A3', secondary: '#006286', text: '#00131C', logo: LOGO_DUBLIN,  font: null },
    { id: 2, name: 'Stadt Wien',          primary: '#FF5A64', secondary: '#D14A52', text: '#000000', logo: LOGO_WIEN,    font: '"WienerMelange_W_Rg", "Mulish", ' + FONT_FALLBACK },
    { id: 3, name: 'Københavns Kommune',  primary: '#000C2E', secondary: '#0A1A4A', text: '#000C2E', logo: LOGO_KBH,     font: '"KBH-Regular", "Archivo", ' + FONT_FALLBACK },
    { id: 4, name: 'City of St. Louis',   primary: '#033D8B', secondary: '#023272', text: '#333333', logo: LOGO_STLOUIS, font: null },
    { id: 5, name: 'Oslo kommune',        primary: '#034B45', secondary: '#023D39', text: '#2C2C2C', logo: LOGO_OSLO,    font: '"OsloSans-Regular", "Inter", ' + FONT_FALLBACK },
    { id: 6, name: 'Lambeth',             primary: '#246797', secondary: '#1E547C', text: '#333333', logo: LOGO_LAMBETH, font: null },
    { id: 7, name: 'Stad Lokeren',        primary: '#025157', secondary: '#024247', text: '#000000', logo: LOGO_LOKEREN, font: null },
    { id: 8, name: 'Engaged California',  primary: '#1C2745', secondary: '#E79450', text: '#1A1A1A', logo: LOGO_CA,      font: '"Noto Sans", ' + FONT_FALLBACK },
  ];
  window.GV_THEMES = GV_THEMES;

  // Load the free substitute/real web fonts once (Google Fonts; Public Sans already loaded by govocal-ui.css).
  (function loadFonts() {
    if (document.getElementById('gv-theme-fonts')) return;
    var l = document.createElement('link');
    l.id = 'gv-theme-fonts';
    l.rel = 'stylesheet';
    l.href = 'https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;700;800&family=Figtree:wght@400;600;700;800&family=Inter:wght@400;600;700;800&family=Mulish:wght@400;600;700;800&family=Noto+Sans:wght@400;600;700;800&display=swap';
    (document.head || document.documentElement).appendChild(l);
  })();

  // ── Bundled custom city faces (real woff2 masters, data URI) + logo sizing. ──
  // These cities self-host proprietary fonts the live platforms serve via @font-face;
  // bundling the Regular master here makes them actually render (bold synthesizes, as on
  // the real sites, which register only the one master). Injected once, self-contained.
  (function loadTenantFontsAndLogoCss() {
    if (document.getElementById('gv-tenant-faces')) return;
    var st = document.createElement('style');
    st.id = 'gv-tenant-faces';
    st.textContent = "@font-face{font-family:'LentiaNova-Neutral';src:url(data:font/woff2;base64,) format('woff2');font-weight:100 900;font-style:normal;font-display:swap;}@font-face{font-family:'OsloSans-Regular';src:url(data:font/woff2;base64,) format('woff2');font-weight:100 900;font-style:normal;font-display:swap;}@font-face{font-family:'KBH-Regular';src:url(data:font/woff2;base64,) format('woff2');font-weight:100 900;font-style:normal;font-display:swap;}@font-face{font-family:'WienerMelange_W_Rg';src:url(data:font/woff2;base64,) format('woff2');font-weight:100 900;font-style:normal;font-display:swap;}[data-gv-logo] img{height:38px;width:auto;max-width:220px;object-fit:contain;display:block}.gv-brand img{height:44px;max-width:240px}.gv-nav-m__logo img{height:34px}.gv-footer__logo img{height:28px}";
    (document.head || document.documentElement).appendChild(st);
  })();

  // ── City logo: real `logo` markup if provided, else a generated placeholder. ──
  function initials(name) {
    return (name || '?').trim().split(/\s+/).map(function (w) { return w.charAt(0); })
      .join('').slice(0, 2).toUpperCase();
  }
  function logoMarkup(theme) {
    if (theme.logo) return theme.logo; // real city logo (inline SVG or <img>)
    return (
      '<span style="display:inline-flex;align-items:center;gap:9px;' +
      "font-family:'Public Sans',system-ui,-apple-system,Segoe UI,Roboto,sans-serif\">" +
      '<span aria-hidden="true" style="display:inline-grid;place-items:center;width:30px;height:30px;' +
      'border-radius:7px;background:' + theme.primary + ';color:#fff;font-weight:800;font-size:13px;' +
      'letter-spacing:-.02em;flex:0 0 auto">' + initials(theme.name) + '</span>' +
      '<span style="font-weight:700;font-size:16px;letter-spacing:-.01em;' +
      'color:var(--gv-tenant-text,#1a1a1a)">' + theme.name + '</span></span>'
    );
  }
  function renderLogos(theme) {
    var slots = document.querySelectorAll('[data-gv-logo]');
    for (var i = 0; i < slots.length; i++) slots[i].innerHTML = logoMarkup(theme);
  }
  window.GVThemeLogo = logoMarkup; // expose for custom rendering

  function findTheme(raw) {
    if (raw == null || raw === '') return GV_THEMES[0];
    var byId = GV_THEMES.find(function (t) { return String(t.id) === String(raw); });
    if (byId) return byId;
    var lc = String(raw).toLowerCase();
    return GV_THEMES.find(function (t) { return t.name.toLowerCase() === lc; }) || GV_THEMES[0];
  }

  function applyTheme(theme) {
    var r = document.documentElement.style;
    r.setProperty('--gv-tenant-primary', theme.primary);
    r.setProperty('--gv-tenant-secondary', theme.secondary);
    r.setProperty('--gv-tenant-text', theme.text);
    if (theme.font) r.setProperty('--gv-font-family', theme.font);
    else r.removeProperty('--gv-font-family'); // fall back to the tokens.css default
    document.documentElement.setAttribute('data-gv-theme', theme.id);
    if (document.body) renderLogos(theme); // body absent on first (pre-parse) call
  }

  function syncUrl(theme) {
    try {
      var url = new URL(window.location.href);
      // Always write ?theme=<id> into the URL — including the default (0) — so the
      // parameter is visible by default and trivially editable to switch cities.
      url.searchParams.set('theme', theme.id);
      window.history.replaceState({}, '', url);
    } catch (e) { /* file:// — ignore */ }
  }

  function current() {
    var params = new URLSearchParams(window.location.search);
    return findTheme(params.get('theme'));
  }

  // Apply ASAP to avoid a flash of the default palette.
  applyTheme(current());

  function renderPicker() {
    if (document.getElementById('gv-theme-picker')) return;
    var active = current();
    var wrap = document.createElement('div');
    wrap.id = 'gv-theme-picker';
    wrap.setAttribute('role', 'group');
    wrap.setAttribute('aria-label', 'Preview city theme');
    wrap.innerHTML =
      '<style>' +
      '#gv-theme-picker{position:fixed;z-index:2147483000;right:16px;bottom:16px;' +
      'display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:10px;' +
      'background:#fff;box-shadow:0 4px 12px -1px rgba(0,0,0,.18);' +
      "font-family:'Public Sans',system-ui,sans-serif;font-size:13px;color:#333}" +
      '#gv-theme-picker .gv-tp-label{font-weight:600;color:#596B7A;white-space:nowrap}' +
      '#gv-theme-picker .gv-tp-swatches{display:flex;gap:6px}' +
      '#gv-theme-picker button.gv-tp-sw{width:24px;height:24px;border-radius:50%;border:2px solid transparent;' +
      'cursor:pointer;padding:0;outline-offset:2px}' +
      '#gv-theme-picker button.gv-tp-sw[aria-pressed="true"]{border-color:#333;box-shadow:0 0 0 2px #fff inset}' +
      '#gv-theme-picker button.gv-tp-sw:focus-visible{outline:2px solid #044D6C}' +
      '#gv-theme-picker .gv-tp-name{min-width:54px;font-weight:600}' +
      '@media (max-width:480px){#gv-theme-picker .gv-tp-name{display:none}}' +
      '</style>' +
      '<span class="gv-tp-label">City</span>' +
      '<span class="gv-tp-swatches"></span>' +
      '<span class="gv-tp-name">' + active.name + '</span>';
    var sw = wrap.querySelector('.gv-tp-swatches');
    var nameEl = wrap.querySelector('.gv-tp-name');
    GV_THEMES.forEach(function (t) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'gv-tp-sw';
      b.style.background = t.primary;
      b.title = t.name;
      b.setAttribute('aria-label', 'Preview ' + t.name + ' theme');
      b.setAttribute('aria-pressed', String(t.id === active.id));
      b.addEventListener('click', function () {
        applyTheme(t);
        syncUrl(t);
        nameEl.textContent = t.name;
        sw.querySelectorAll('button').forEach(function (x) { x.setAttribute('aria-pressed', 'false'); });
        b.setAttribute('aria-pressed', 'true');
      });
      sw.appendChild(b);
    });
    document.body.appendChild(wrap);
  }

  // Opt out of the on-screen picker with <body data-gv-theme-picker="off">.
  function init() {
    syncUrl(current());
    renderLogos(current()); // fill any [data-gv-logo] slots now that <body> exists
    if (document.body && document.body.getAttribute('data-gv-theme-picker') !== 'off') {
      renderPicker();
    }
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
